DROP TABLE IF EXISTS `check_request`;
CREATE TABLE `check_request` (
  `id` int NOT NULL AUTO_INCREMENT,
  `register_id` int DEFAULT NULL,
  `medical_technology_id` int DEFAULT NULL,
  `check_info` varchar(512) DEFAULT NULL,
  `check_position` varchar(255) DEFAULT NULL,
  `creation_time` datetime DEFAULT NULL,
  `check_employee_id` int DEFAULT NULL COMMENT '查检医生id',
  `inputcheck_employee_id` int DEFAULT NULL COMMENT '结果输入医生id',
  `check_time` datetime DEFAULT NULL COMMENT '检查时间',
  `check_result` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '结果',
  `check_state` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '状态(已开立,已缴费,执行完成,已出结果,已退费,已作废)',
  `check_remark` varchar(512) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb3;

