-- ----------------------------
-- Table structure for `register`
-- ----------------------------
DROP TABLE IF EXISTS `register`;
CREATE TABLE `register` (
  `id` int NOT NULL AUTO_INCREMENT,
  `case_number` varchar(64) DEFAULT NULL COMMENT '病历号',
  `real_name` varchar(64) DEFAULT NULL COMMENT '姓名',
  `gender` varchar(6) DEFAULT NULL COMMENT '性别（男、女）',
  `card_number` varchar(18) DEFAULT NULL COMMENT '身份证号',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `age` int DEFAULT NULL COMMENT '年龄',
  `age_type` varchar(6) DEFAULT NULL COMMENT '年龄类型（年、天）',
  `home_address` varchar(64) DEFAULT NULL COMMENT '家庭住址',
  `visit_date` datetime DEFAULT NULL COMMENT '本次看诊日期',
  `noon` varchar(6) DEFAULT NULL COMMENT '午别（上午、下午）',
  `deptment_id` int DEFAULT NULL COMMENT '本次挂号科室id',
  `employee_id` int DEFAULT NULL COMMENT '本次挂号医生id',
  `regist_level_id` int DEFAULT NULL COMMENT '本次挂号级别id',
  `settle_category_id` int DEFAULT NULL COMMENT '结算类别id',
  `is_book` char(2) DEFAULT NULL COMMENT '病历本要否（要、否）',
  `regist_method` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL COMMENT '收费方式（现金、银行卡、微信、医保卡、支付宝）',
  `visit_state` int DEFAULT NULL COMMENT '本次看诊状态（1-已挂号\n2-医生接诊\n3-看诊结束\n4-已退号）',
  `regist_money` decimal(8,2) DEFAULT NULL COMMENT '挂号金额',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb3;

